// Turn the raw Gmail message into clean fields, and flag mail that no person should answer.
const settings = $('Settings').item.json;
const email = $('Gmail Trigger').item.json;
const headers = email.headers ?? {};

// Some emails have only HTML. Turn it into plain text.
function htmlToText(html) {
  return String(html ?? '')
    .replace(/<(style|script|head)[\s\S]*?<\/\1>/gi, ' ')
    .replace(/<br\s*\/?>|<\/(p|div|li|tr|h[1-6])>/gi, '\n')
    .replace(/<\/?(a|b|i|u|em|strong|span|font|small|code|mark|sub|sup) [^>]*>/gi, '') // inline tags: no extra space
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/[ \t]+/g, ' ')
    .replace(/ *\n */g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

const body = (String(email.text ?? '').trim() || htmlToText(email.html)).slice(0, 6000) || '(empty message)';
const fromEmail = email.from?.value?.[0]?.address ?? '';

// Header values look like "Precedence: bulk", so test the whole line.
let skipReason = '';
const skipSenders = String(settings.skipSenderPatterns ?? '').split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
if (skipSenders.some(s => fromEmail.toLowerCase().includes(s))) {
  skipReason = 'Sender is on the skip list.';
} else if (settings.skipBulkEmail) {
  if (headers['list-unsubscribe']) skipReason = 'Newsletter or mailing list.';
  else if (/:\s*(bulk|list|junk)\b/i.test(headers['precedence'] ?? '')) skipReason = 'Bulk email.';
  else if (headers['auto-submitted'] && !/:\s*no\b/i.test(headers['auto-submitted'])) skipReason = 'Automatic reply.';
}

return {
  json: {
    messageId: email.id,
    threadId: email.threadId,
    from: email.from?.text ?? '',
    fromEmail,
    subject: email.subject || '(no subject)',
    body,
    receivedAt: email.date ?? $now.toISO(),
    skipReason,
  },
};

