// Check the AI answer. Never trust it blindly.
const config = $('Settings').item.json;
const ai = $json.output ?? {};
const toList = (text, sep) => String(text ?? '').split(sep).map(s => s.trim()).filter(Boolean);

// Category names are the text before ':' on each line of the Settings list.
const allowed = toList(config.categories, '\n').map(line => line.split(':')[0].trim());
const alwaysReview = toList(config.alwaysReviewCategories, ',');

const knownCategory = allowed.includes(ai.category);
const category = knownCategory ? ai.category : config.fallbackCategory;

let confidence = Number(ai.confidence);
if (!Number.isFinite(confidence)) confidence = 0;
confidence = Math.min(1, Math.max(0, confidence));

const draftReply = String(ai.draft_reply ?? '').trim();

// Collect every reason a person must look at this email.
const reasons = [];
if (ai.needs_human_review === true) reasons.push(ai.review_reason || 'AI asked for a human review.');
if (!knownCategory) reasons.push(`AI gave an unknown category (${ai.category ?? 'none'}).`);
if (!draftReply) reasons.push('AI did not write a draft.');
if (confidence < config.confidenceThreshold) reasons.push(`Low confidence (${Math.round(confidence * 100)}%).`);
if (alwaysReview.includes(category)) reasons.push(`${category} always needs a person.`);

const sendAlert = reasons.length > 0;

return {
  json: {
    category,
    confidence,
    summary: String(ai.summary ?? ''),
    draftReply,
    sendAlert,
    reviewReason: reasons.join(' '),
    status: sendAlert ? 'Needs Review' : 'Drafted',
  },
};

